import java.util.ArrayList;
import java.util.HashSet;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.TreeSet;
import java.util.TreeMap;
import java.util.Iterator;
import java.util.Collections;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Java Data Structures Fundamentals ===");

        // 1. ArrayList - Dynamic Array
        System.out.println("\n--- 1. ArrayList (Resizable Array) ---");

        ArrayList<String> fruits = new ArrayList<>();

        // Adding elements
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Orange");
        fruits.add("Mango");
        fruits.add("Banana");  // Duplicates allowed

        System.out.println("Fruits: " + fruits);
        System.out.println("Size: " + fruits.size());
        System.out.println("Element at index 2: " + fruits.get(2));

        // Modifying
        fruits.set(1, "Grapes");
        System.out.println("After modification: " + fruits);

        // Removing
        fruits.remove("Banana");  // Removes first occurrence
        System.out.println("After removing Banana: " + fruits);

        // Checking
        System.out.println("Contains Apple? " + fruits.contains("Apple"));
        System.out.println("Is empty? " + fruits.isEmpty());

        // Sorting
        Collections.sort(fruits);
        System.out.println("Sorted: " + fruits);

        // Iterating
        System.out.print("Iterating: ");
        for (String fruit : fruits) {
            System.out.print(fruit + " ");
        }
        System.out.println();

        // 2. LinkedList - Doubly Linked List
        System.out.println("\n--- 2. LinkedList ---");

        LinkedList<Integer> numbers = new LinkedList<>();
        numbers.add(10);
        numbers.add(20);
        numbers.add(30);
        numbers.addFirst(5);   // Add at beginning
        numbers.addLast(40);   // Add at end

        System.out.println("Numbers: " + numbers);
        System.out.println("First: " + numbers.getFirst());
        System.out.println("Last: " + numbers.getLast());

        numbers.removeFirst();
        numbers.removeLast();
        System.out.println("After removing first & last: " + numbers);

        // 3. HashSet - Unique Elements, No Order
        System.out.println("\n--- 3. HashSet (No Duplicates) ---");

        HashSet<String> carSet = new HashSet<>();
        carSet.add("Toyota");
        carSet.add("Honda");
        carSet.add("Ford");
        carSet.add("Toyota");  // Duplicate - won't be added
        carSet.add("BMW");

        System.out.println("Car Set: " + carSet);
        System.out.println("Size: " + carSet.size());
        System.out.println("Contains Honda? " + carSet.contains("Honda"));

        // Iterating HashSet
        System.out.print("Iterating HashSet: ");
        for (String car : carSet) {
            System.out.print(car + " ");
        }
        System.out.println();

        // 4. TreeSet - Sorted Unique Elements
        System.out.println("\n--- 4. TreeSet (Sorted Unique) ---");

        TreeSet<Integer> scores = new TreeSet<>();
        scores.add(85);
        scores.add(92);
        scores.add(78);
        scores.add(92);  // Duplicate
        scores.add(65);

        System.out.println("Scores: " + scores);
        System.out.println("First (lowest): " + scores.first());
        System.out.println("Last (highest): " + scores.last());
        System.out.println("Higher than 80: " + scores.higher(80));

        // 5. HashMap - Key-Value Pairs
        System.out.println("\n--- 5. HashMap (Key-Value Pairs) ---");

        HashMap<String, Integer> studentGrades = new HashMap<>();

        // Adding key-value pairs
        studentGrades.put("Ali", 85);
        studentGrades.put("Sara", 92);
        studentGrades.put("Ahmed", 78);
        studentGrades.put("Ali", 88);  // Updates existing key

        System.out.println("Student Grades: " + studentGrades);
        System.out.println("Ali's grade: " + studentGrades.get("Ali"));
        System.out.println("Contains Sara? " + studentGrades.containsKey("Sara"));

        // Iterating HashMap
        System.out.println("\nIterating HashMap:");
        for (String name : studentGrades.keySet()) {
            System.out.println(name + ": " + studentGrades.get(name));
        }

        // 6. TreeMap - Sorted Key-Value Pairs
        System.out.println("\n--- 6. TreeMap (Sorted Keys) ---");

        TreeMap<String, String> countries = new TreeMap<>();
        countries.put("USA", "Washington");
        countries.put("Pakistan", "Islamabad");
        countries.put("India", "Delhi");
        countries.put("China", "Beijing");

        System.out.println("Countries: " + countries);
        System.out.println("First country: " + countries.firstKey());
        System.out.println("Capital of Pakistan: " + countries.get("Pakistan"));

        // 7. Iterators
        System.out.println("\n--- 7. Iterators ---");

        ArrayList<String> colors = new ArrayList<>();
        colors.add("Red");
        colors.add("Green");
        colors.add("Blue");
        colors.add("Yellow");

        System.out.println("Using Iterator:");
        Iterator<String> iterator = colors.iterator();
        while (iterator.hasNext()) {
            String color = iterator.next();
            System.out.println(color);
            if (color.equals("Green")) {
                iterator.remove();  // Safe removal during iteration
            }
        }
        System.out.println("After removing Green: " + colors);

        // 8. Stack - LIFO
        System.out.println("\n--- 8. Stack (LIFO) ---");

        java.util.Stack<String> stack = new java.util.Stack<>();
        stack.push("First");
        stack.push("Second");
        stack.push("Third");

        System.out.println("Stack: " + stack);
        System.out.println("Top element: " + stack.peek());
        System.out.println("Popped: " + stack.pop());
        System.out.println("Stack after pop: " + stack);

        // 9. Queue - FIFO
        System.out.println("\n--- 9. Queue (FIFO) ---");

        java.util.Queue<String> queue = new java.util.LinkedList<>();
        queue.add("First");
        queue.add("Second");
        queue.add("Third");

        System.out.println("Queue: " + queue);
        System.out.println("Front element: " + queue.peek());
        System.out.println("Removed: " + queue.remove());
        System.out.println("Queue after removal: " + queue);

        // 10. Performance Comparison
        System.out.println("\n=== Data Structures Comparison ===");
        System.out.println("\n1. ArrayList vs LinkedList:");
        System.out.println("   ArrayList: Fast random access, slow insert/delete in middle");
        System.out.println("   LinkedList: Fast insert/delete anywhere, slow random access");

        System.out.println("\n2. HashSet vs TreeSet:");
        System.out.println("   HashSet: Faster, no order");
        System.out.println("   TreeSet: Slower, sorted order");

        System.out.println("\n3. HashMap vs TreeMap:");
        System.out.println("   HashMap: Faster, no order");
        System.out.println("   TreeMap: Slower, sorted by keys");

        System.out.println("\n=== When to Use What? ===");
        System.out.println("• Need indexed access? → ArrayList");
        System.out.println("• Frequent insertions/deletions? → LinkedList");
        System.out.println("• Need unique elements? → HashSet");
        System.out.println("• Need sorted unique elements? → TreeSet");
        System.out.println("• Key-value storage? → HashMap");
        System.out.println("• Sorted key-value storage? → TreeMap");

        // Practical Example: Student Management System
        System.out.println("\n=== Practical Example: Student Management ===");

        HashMap<String, ArrayList<Integer>> studentMarks = new HashMap<>();

        // Student Ali's marks
        ArrayList<Integer> aliMarks = new ArrayList<>();
        aliMarks.add(85);
        aliMarks.add(90);
        aliMarks.add(78);
        studentMarks.put("Ali", aliMarks);

        // Student Sara's marks
        ArrayList<Integer> saraMarks = new ArrayList<>();
        saraMarks.add(92);
        saraMarks.add(88);
        saraMarks.add(95);
        studentMarks.put("Sara", saraMarks);

        // Display all students and their marks
        System.out.println("\nStudent Marks Database:");
        for (String student : studentMarks.keySet()) {
            System.out.print(student + ": ");
            ArrayList<Integer> marks = studentMarks.get(student);
            int total = 0;
            for (int mark : marks) {
                System.out.print(mark + " ");
                total += mark;
            }
            double average = total / (double) marks.size();
            System.out.printf(" (Average: %.2f)\n", average);
        }

        // Find top student
        String topStudent = "";
        double highestAverage = 0;

        for (String student : studentMarks.keySet()) {
            ArrayList<Integer> marks = studentMarks.get(student);
            int total = 0;
            for (int mark : marks) total += mark;
            double average = total / (double) marks.size();

            if (average > highestAverage) {
                highestAverage = average;
                topStudent = student;
            }
        }

        System.out.printf("\nTop Student: %s (Average: %.2f)\n", topStudent, highestAverage);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Java Collections Framework ===");

        // 1. Understanding the Hierarchy
        System.out.println("\n--- 1. Collections Framework Hierarchy ---");

        System.out.println("\nInterface: Collection");
        System.out.println("    ├── List (Ordered, allows duplicates)");
        System.out.println("    │     ├── ArrayList (Resizable array)");
        System.out.println("    │     └── LinkedList (Doubly linked list)");
        System.out.println("    │");
        System.out.println("    └── Set (Unique elements)");
        System.out.println("          ├── HashSet (Hash table)");
        System.out.println("          ├── LinkedHashSet (Maintains insertion order)");
        System.out.println("          └── TreeSet (Sorted)");

        System.out.println("\nInterface: Map (Key-Value pairs)");
        System.out.println("    ├── HashMap (Hash table)");
        System.out.println("    ├── LinkedHashMap (Maintains insertion order)");
        System.out.println("    └── TreeMap (Sorted by keys)");

        // 2. List Interface and Implementations
        System.out.println("\n--- 2. List Interface ---");

        // Using List interface reference
        List<String> fruits = new ArrayList<>();
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Orange");

        System.out.println("List fruits: " + fruits);
        System.out.println("Size: " + fruits.size());
        System.out.println("Get index 1: " + fruits.get(1));

        // Switching implementation - Polymorphism in action!
        List<Integer> numbers = new LinkedList<>();
        numbers.add(10);
        numbers.add(20);
        numbers.add(30);

        System.out.println("\nLinkedList numbers: " + numbers);

        // Common List methods
        System.out.println("\nCommon List Methods:");
        System.out.println("add(element), get(index), remove(index/element)");
        System.out.println("size(), isEmpty(), contains(element)");
        System.out.println("indexOf(element), subList(from, to)");

        // 3. Set Interface and Implementations
        System.out.println("\n--- 3. Set Interface ---");

        // HashSet - No order
        Set<String> hashSet = new HashSet<>();
        hashSet.add("Red");
        hashSet.add("Green");
        hashSet.add("Blue");
        hashSet.add("Red");  // Duplicate
        hashSet.add("Yellow");

        System.out.println("HashSet (no order): " + hashSet);

        // LinkedHashSet - Insertion order maintained
        Set<String> linkedHashSet = new LinkedHashSet<>();
        linkedHashSet.add("Red");
        linkedHashSet.add("Green");
        linkedHashSet.add("Blue");
        linkedHashSet.add("Yellow");

        System.out.println("LinkedHashSet (insertion order): " + linkedHashSet);

        // TreeSet - Sorted order
        Set<String> treeSet = new TreeSet<>();
        treeSet.add("Red");
        treeSet.add("Green");
        treeSet.add("Blue");
        treeSet.add("Yellow");

        System.out.println("TreeSet (sorted order): " + treeSet);

        // Common Set methods
        System.out.println("\nCommon Set Methods:");
        System.out.println("add(element), remove(element), contains(element)");
        System.out.println("size(), isEmpty(), clear()");

        // Set operations
        Set<Integer> set1 = new HashSet<>(Arrays.asList(1, 2, 3, 4, 5));
        Set<Integer> set2 = new HashSet<>(Arrays.asList(4, 5, 6, 7, 8));

        System.out.println("\nSet Operations:");
        System.out.println("Set1: " + set1);
        System.out.println("Set2: " + set2);

        // Union
        Set<Integer> union = new HashSet<>(set1);
        union.addAll(set2);
        System.out.println("Union: " + union);

        // Intersection
        Set<Integer> intersection = new HashSet<>(set1);
        intersection.retainAll(set2);
        System.out.println("Intersection: " + intersection);

        // Difference
        Set<Integer> difference = new HashSet<>(set1);
        difference.removeAll(set2);
        System.out.println("Difference (set1 - set2): " + difference);

        // 4. Map Interface and Implementations
        System.out.println("\n--- 4. Map Interface ---");

        // HashMap - No order
        Map<String, Integer> hashMap = new HashMap<>();
        hashMap.put("Ali", 25);
        hashMap.put("Sara", 22);
        hashMap.put("Ahmed", 30);
        hashMap.put("Ali", 26);  // Updates existing key

        System.out.println("HashMap (no order): " + hashMap);

        // LinkedHashMap - Insertion order maintained
        Map<String, Integer> linkedHashMap = new LinkedHashMap<>();
        linkedHashMap.put("Ali", 25);
        linkedHashMap.put("Sara", 22);
        linkedHashMap.put("Ahmed", 30);

        System.out.println("LinkedHashMap (insertion order): " + linkedHashMap);

        // TreeMap - Sorted by keys
        Map<String, Integer> treeMap = new TreeMap<>();
        treeMap.put("Ali", 25);
        treeMap.put("Sara", 22);
        treeMap.put("Ahmed", 30);

        System.out.println("TreeMap (sorted by keys): " + treeMap);

        // Common Map methods
        System.out.println("\nCommon Map Methods:");
        System.out.println("put(key, value), get(key), remove(key)");
        System.out.println("containsKey(key), containsValue(value)");
        System.out.println("keySet(), values(), entrySet()");

        // Iterating through Map
        System.out.println("\nIterating Map entries:");
        for (Map.Entry<String, Integer> entry : hashMap.entrySet()) {
            System.out.println("Key: " + entry.getKey() + ", Value: " + entry.getValue());
        }

        // 5. Collections Utility Class
        System.out.println("\n--- 5. Collections Utility Class ---");

        List<Integer> nums = new ArrayList<>(Arrays.asList(5, 2, 8, 1, 9, 3));
        System.out.println("Original list: " + nums);

        // Sorting
        Collections.sort(nums);
        System.out.println("Sorted: " + nums);

        // Reverse
        Collections.reverse(nums);
        System.out.println("Reversed: " + nums);

        // Shuffle
        Collections.shuffle(nums);
        System.out.println("Shuffled: " + nums);

        // Binary search (list must be sorted first)
        Collections.sort(nums);
        int index = Collections.binarySearch(nums, 5);
        System.out.println("Binary search for 5: index " + index);

        // Max and Min
        System.out.println("Max: " + Collections.max(nums));
        System.out.println("Min: " + Collections.min(nums));

        // 6. Iterator and ListIterator
        System.out.println("\n--- 6. Iterators ---");

        List<String> colors = new ArrayList<>(Arrays.asList("Red", "Green", "Blue", "Yellow"));

        // Iterator (forward only)
        System.out.println("Using Iterator:");
        Iterator<String> iterator = colors.iterator();
        while (iterator.hasNext()) {
            System.out.println(iterator.next());
        }

        // ListIterator (bidirectional)
        System.out.println("\nUsing ListIterator (backwards):");
        ListIterator<String> listIterator = colors.listIterator(colors.size());
        while (listIterator.hasPrevious()) {
            System.out.println(listIterator.previous());
        }

        // 7. Choosing the Right Collection
        System.out.println("\n=== Choosing the Right Collection ===");

        System.out.println("\nWhen to use List:");
        System.out.println("• Need to maintain insertion order");
        System.out.println("• Allow duplicate elements");
        System.out.println("• Need index-based access");
        System.out.println("• ArrayList: Frequent get/set operations");
        System.out.println("• LinkedList: Frequent add/remove operations");

        System.out.println("\nWhen to use Set:");
        System.out.println("• Need unique elements only");
        System.out.println("• Don't care about order: HashSet");
        System.out.println("• Need insertion order: LinkedHashSet");
        System.out.println("• Need sorted order: TreeSet");

        System.out.println("\nWhen to use Map:");
        System.out.println("• Need key-value pairs");
        System.out.println("• Don't care about order: HashMap");
        System.out.println("• Need insertion order: LinkedHashMap");
        System.out.println("• Need sorted keys: TreeMap");

        // 8. Generics in Collections
        System.out.println("\n--- 7. Generics in Collections ---");

        // Without generics (old way - not type safe)
        List rawList = new ArrayList();  // Raw type
        rawList.add("Hello");
        rawList.add(123);  // Mixed types allowed

        // With generics (type safe)
        List<String> stringList = new ArrayList<>();
        stringList.add("Hello");
        // stringList.add(123);  // Compile error!

        System.out.println("Generic List ensures type safety!");

        // 9. Practical Example: Student Database
        System.out.println("\n=== Practical Example: Student Database ===");

        class Student {
            String name;
            int id;
            double gpa;

            Student(String name, int id, double gpa) {
                this.name = name;
                this.id = id;
                this.gpa = gpa;
            }

            @Override
            public String toString() {
                return name + " (ID: " + id + ", GPA: " + gpa + ")";
            }
        }

        // Using different collections for different purposes
        List<Student> studentList = new ArrayList<>();
        Set<Integer> studentIds = new HashSet<>();
        Map<Integer, Student> studentMap = new HashMap<>();

        // Add students
        Student s1 = new Student("Ali", 101, 3.8);
        Student s2 = new Student("Sara", 102, 3.9);
        Student s3 = new Student("Ahmed", 103, 3.7);

        studentList.add(s1);
        studentList.add(s2);
        studentList.add(s3);

        studentIds.add(s1.id);
        studentIds.add(s2.id);
        studentIds.add(s3.id);

        studentMap.put(s1.id, s1);
        studentMap.put(s2.id, s2);
        studentMap.put(s3.id, s3);

        System.out.println("\nStudent List (maintains order):");
        for (Student s : studentList) {
            System.out.println(s);
        }

        System.out.println("\nStudent IDs (unique): " + studentIds);

        System.out.println("\nStudent Map (fast lookup by ID):");
        System.out.println("Student with ID 102: " + studentMap.get(102));

        // 10. Performance Comparison
        System.out.println("\n=== Performance Characteristics ===");
        System.out.println("\nArrayList vs LinkedList:");
        System.out.println("• ArrayList: O(1) for get/set, O(n) for add/remove in middle");
        System.out.println("• LinkedList: O(n) for get/set, O(1) for add/remove at ends");

        System.out.println("\nHashSet vs TreeSet:");
        System.out.println("• HashSet: O(1) for add/remove/contains (average)");
        System.out.println("• TreeSet: O(log n) for add/remove/contains");

        System.out.println("\nHashMap vs TreeMap:");
        System.out.println("• HashMap: O(1) for get/put (average)");
        System.out.println("• TreeMap: O(log n) for get/put");
    }
}

