        System.out.println("\n=== Comparison ===");
        System.out.println("Use ArrayList for: Frequent get/set operations");
        System.out.println("Use LinkedList for: Frequent add/remove in middle");
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Sorting Lists ===");

        // Sort Strings alphabetically
        ArrayList<String> fruits = new ArrayList<>();
        fruits.add("Mango");
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Orange");

        System.out.println("Original: " + fruits);

        Collections.sort(fruits);
        System.out.println("Sorted A-Z: " + fruits);

        // Sort in reverse order
        Collections.sort(fruits, Collections.reverseOrder());
        System.out.println("Sorted Z-A: " + fruits);

        System.out.println("\n=== Sorting Numbers ===");

        // Sort Integers
        ArrayList<Integer> numbers = new ArrayList<>();
        numbers.add(42);
        numbers.add(15);
        numbers.add(8);
        numbers.add(30);

        System.out.println("Original: " + numbers);

        Collections.sort(numbers);
        System.out.println("Ascending: " + numbers);

        Collections.sort(numbers, Collections.reverseOrder());
        System.out.println("Descending: " + numbers);

        System.out.println("\n=== Sorting Custom Objects ===");

        // Sort custom objects
        class Student implements Comparable<Student> {
            String name;
            int marks;

            Student(String name, int marks) {
                this.name = name;
                this.marks = marks;
            }

            @Override
            public int compareTo(Student other) {
                return this.name.compareTo(other.name);
            }

            @Override
            public String toString() {
                return name + ": " + marks;
            }
        }

        List<Student> students = new ArrayList<>();
        students.add(new Student("Ali", 85));
        students.add(new Student("Sara", 92));
        students.add(new Student("Ahmed", 78));

        Collections.sort(students);
        System.out.println("Students sorted by name:");
        for (Student s : students) {
            System.out.println(s);
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== Set Interface Examples ===");

        // HashSet - No order, fastest
        Set<String> hashSet = new HashSet<>();
        hashSet.add("Apple");
        hashSet.add("Banana");
        hashSet.add("Apple");  // Duplicate ignored
        hashSet.add("Orange");

        System.out.println("HashSet: " + hashSet);

        // TreeSet - Sorted order
        Set<String> treeSet = new TreeSet<>();
        treeSet.add("Mango");
        treeSet.add("Apple");
        treeSet.add("Cherry");

        System.out.println("TreeSet (sorted): " + treeSet);

        // LinkedHashSet - Insertion order
        Set<String> linkedHashSet = new LinkedHashSet<>();
        linkedHashSet.add("Third");
        linkedHashSet.add("First");
        linkedHashSet.add("Second");

        System.out.println("LinkedHashSet (insertion order): " + linkedHashSet);

        // Set operations
        Set<Integer> set1 = new HashSet<>(Arrays.asList(1, 2, 3, 4));
        Set<Integer> set2 = new HashSet<>(Arrays.asList(3, 4, 5, 6));

        // Union
        Set<Integer> union = new HashSet<>(set1);
        union.addAll(set2);
        System.out.println("\nUnion: " + union);

        // Intersection
        Set<Integer> intersection = new HashSet<>(set1);
        intersection.retainAll(set2);
        System.out.println("Intersection: " + intersection);

        // Difference
        Set<Integer> difference = new HashSet<>(set1);
        difference.removeAll(set2);
        System.out.println("Difference: " + difference);

        // Practical example: Remove duplicates from list
        System.out.println("\n=== Remove Duplicates ===");
        List<String> withDuplicates = Arrays.asList("A", "B", "A", "C", "B");
        Set<String> uniqueSet = new HashSet<>(withDuplicates);
        System.out.println("Original: " + withDuplicates);
        System.out.println("Unique: " + uniqueSet);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        System.out.println("=== HashSet Examples ===");

        // Creating HashSet
        HashSet<String> fruits = new HashSet<>();

        // Adding elements
        fruits.add("Apple");
        fruits.add("Banana");
        fruits.add("Orange");
        fruits.add("Apple");  // Duplicate - ignored
        fruits.add("Mango");

