        System.out.println("TailSet (greater than or equal to 30): " + numbers.tailSet(30));
        System.out.println("SubSet (20 to 50): " + numbers.subSet(20, 50));

        // Poll methods (retrieve and remove)
        System.out.println("\nPoll methods:");
        System.out.println("Poll first: " + numbers.pollFirst());
        System.out.println("Poll last: " + numbers.pollLast());
        System.out.println("After poll: " + numbers);

        // TreeSet vs HashSet comparison
        System.out.println("\n=== TreeSet vs HashSet ===");

        HashSet<String> hashSet = new HashSet<>();
        hashSet.add("Zebra");
        hashSet.add("Apple");
        hashSet.add("Monkey");

        TreeSet<String> treeSet = new TreeSet<>();
        treeSet.add("Zebra");
        treeSet.add("Apple");
        treeSet.add("Monkey");

        System.out.println("HashSet (no order): " + hashSet);
        System.out.println("TreeSet (sorted): " + treeSet);

        // Descending order
        System.out.println("\n=== Descending Order ===");
        System.out.println("Descending set: " + treeSet.descendingSet());

        // Iterator in descending order
