        }

        // TreeSet with custom comparator
        System.out.println("\n=== Custom Sorting ===");

        // Sort by string length
        TreeSet<String> lengthSorted = new TreeSet<>(
            (s1, s2) -> {
                int lenCompare = Integer.compare(s1.length(), s2.length());
                if (lenCompare == 0) {
                    return s1.compareTo(s2);
                }
                return lenCompare;
            }
        );

        lengthSorted.add("Apple");
        lengthSorted.add("Kiwi");
        lengthSorted.add("Banana");
        lengthSorted.add("Mango");

        System.out.println("Sorted by length: " + lengthSorted);

