        System.out.println("Top score: " + scores.last());
        System.out.println("Lowest score: " + scores.first());
        System.out.println("Scores above 85: " + scores.tailSet(86));

        // Find student in top 3
        System.out.println("\nTop 3 scores:");
        Iterator<Integer> top3 = scores.descendingIterator();
        for (int i = 0; i < 3 && top3.hasNext(); i++) {
            System.out.println(top3.next());
        }

        // Performance characteristics
        System.out.println("\n=== Performance ===");
        System.out.println("• add/remove/contains: O(log n)");
        System.out.println("• first/last: O(log n)");
        System.out.println("• headSet/tailSet: O(log n)");
        System.out.println("• Memory: More than HashSet (stores tree structure)");

        System.out.println("\n=== When to Use TreeSet ===");
        System.out.println("1. Need sorted unique elements");
        System.out.println("2. Need range queries (headSet, tailSet)");
        System.out.println("3. Need navigation methods (higher, lower)");
        System.out.println("4. Don't need fastest performance");
    }
}

