        System.out.println("After putAll: " + map1);

        // Compute if absent
        map1.computeIfAbsent("D", k -> 5);
        System.out.println("After computeIfAbsent: " + map1);

        // Compute if present
        map1.computeIfPresent("A", (k, v) -> v * 10);
        System.out.println("After computeIfPresent: " + map1);

        // Merge with custom function
        map1.merge("B", 10, (oldValue, newValue) -> oldValue + newValue);
        System.out.println("After merge: " + map1);

        // Performance demonstration
        System.out.println("\n=== Performance Characteristics ===");
        System.out.println("• get/put/remove: O(1) average time");
