        System.out.println("Value for null key: " + nullMap.get(null));

        // Clear HashMap
        studentMarks.clear();
        System.out.println("\nAfter clear, empty? " + studentMarks.isEmpty());

        System.out.println("\n=== When to Use HashMap ===");
        System.out.println("1. Need fast key-value lookups");
        System.out.println("2. Don't care about order");
        System.out.println("3. Need to store mappings");
        System.out.println("4. Counting frequencies");

